# Funktion, um den SVG-Code zu extrahieren und als Datei zu speichern
def save_svg(name, data_url):
    if data_url.startswith("data:image/svg+xml;base64,"):
        # Base64-decodiert
        b64_data = data_url.split("base64,")[1]
        svg_data = base64.b64decode(b64_data).decode("utf-8")
    elif data_url.startswith("data:image/svg+xml,"):
        # URL-dekodiert (kein Base64)
        encoded_svg = data_url.split("data:image/svg+xml,")[1]
        svg_data = urllib.parse.unquote(encoded_svg)
    else:
        raise ValueError("Unbekanntes Datenformat")

    svg_filename = f"{name}.svg"
    with open(svg_filename, "w", encoding="utf-8") as f:
        f.write(svg_data)
    return svg_filename


# Für jedes Icon extrahieren und in PNG umwandeln
for name, data_url in data_urls.items():
    svg_file = save_svg(name, data_url)
    png_file = f"{name}.png"

    # Konvertieren von SVG zu PNG (CairoSVG)
    try:
        cairosvg.svg2png(url=svg_file, write_to=png_file)
        print(f"{png_file} wurde erfolgreich erstellt.")
    except Exception as e:
        print(f"Fehler bei {name}: {e}")

